INSERT OR REPLACE INTO programs (id, name, theme_concept, active) VALUES ('week1', 'Transit Cycle 01', 'MERIDIAN // OPS — long-haul transit vessel systems terminal', 1);
INSERT OR REPLACE INTO categories (id, program_id, name, label, kind, sort_order) VALUES ('week1-propulsion', 'week1', 'propulsion', 'PROPULSION', 'sets', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-daily-daily-steps-target', 'week1-propulsion', NULL, 'Daily steps target', 'Aim for 10,000-20,000 steps/day. Since you have a Fitbit Inspire 3, use its step count directly instead of guessing — no need for a separate tracking method. Since you work from home and don''t drive, most people''s "incidental" steps (parking lots, walking to the car, errands) won''t apply to you — so this needs to be built in deliberately rather than assumed to happen on its own: · Treadmill walking during calls/meetings (your Weslo has manual incline — even a slow pace adds up over an 8+ hour workday) · A dedicated walk block once or twice a day (outside when weather/energy allows, treadmill otherwise) — even 2 x 20-30 min walks gets you 4,000-6,000 steps before anything else · Standing/pacing during phone calls instead of sitting · Check your Fitbit for a few days first to see your real baseline before assuming you''re close to 10k — desk job + delivery groceries + no driving often means starting closer to 2,000-4,000 steps/day, and going from there to 10k+ is itself a big, worthwhile jump', '{"kind":"checkbox"}', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-bench-press', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Bench press', 'Empty barbell (35 lb) only this week — focus: shoulder blades pinned, controlled descent to chest', '{"targetText":"3 x 8"}', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-powerblock-row-bent-over-or-single-arm', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Powerblock row (bent over or single-arm)', '20-25 lb — squeeze shoulder blade, don''t yank with momentum', '{"targetText":"3 x 10"}', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-kettlebell-overhead-press-seated-or-stan', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Kettlebell overhead press (seated or standing)', '10-15 lb — press straight up, don''t lean back. **Alternative:** since you can OHP the empty 35lb barbell for a few reps, feel free to use that instead 1-2x this week to see how it feels — or the fixed 15-20lb barbell as a middle option', '{"targetText":"3 x 8/side"}', 3);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-pull-up-bar-dead-hang-scap-pulls', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Pull-up bar: dead hang + scap pulls', 'Bodyweight — this builds shoulder stability before real pull-ups. **Given your trap/neck tendency:** keep shoulders pulled down away from ears the whole hang, don''t let them shrug up — if your neck/traps start to feel it, shorten the hang time rather than pushing through', '{"targetText":"3 x max hang (aim 15-20 sec) + 8 scap pulls"}', 4);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-push-up-progression', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Push-up progression', 'Incline push-ups: hands on the bench, feet on floor, **hands set wide** (you already know this helps you). Lower chest to bench, controlled. **Skip the knee push-up regression entirely** — with hypermobile kneecaps, kneeling on the floor under load isn''t worth it. Instead, progress by lowering the incline height (bench → lower surface → floor) rather than moving to your knees', '{"targetText":"3 x max effort (aim 5-8)"}', 5);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-pulley-face-pulls', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Pulley face pulls', 'Light band/plate tension — elbows high, squeeze shoulder blades. **Given your trap/neck tendency:** keep the movement in the shoulder blades, not the neck/traps — if you feel it creeping into your neck, drop the tension further', '{"targetText":"3 x 15"}', 6);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-1-tuesday-upper-body-dumbbell-bicep-curl-tricep-pushdown-pull', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Dumbbell bicep curl + tricep pushdown (pulley)', 'EZ curl bar for curls (easier wrist angle than straight dumbbell curls, worth using given the hypermobility) + light pulley tension for pushdowns', '{"targetText":"2 x 12 each"}', 7);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-kettlebell-goblet-squat', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Kettlebell goblet squat', '15-20 lb held at chest, **heels on squat wedges.** This is your main squat pattern this week, NOT the barbell. The wedges reduce how much ankle mobility you need to stay upright — if the forward lean was partly an ankle range issue, this alone may fix a lot of it. Sit back like sitting in a chair, chest up, weight even through the foot', '{"targetText":"4 x 8"}', 8);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-barbell-squat-empty-bar-only', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Barbell squat (empty bar only)', '35 lb only, **heels on wedges, standing on the plywood platform.** Purely to practice bar position on back + the same upright-torso cue as the goblet squat, low reps', '{"targetText":"2 x 5"}', 9);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-kettlebell-rdl-romanian-deadlift', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Kettlebell RDL / Romanian deadlift', '20-25 lb — hinge at hips, slight knee bend, feel hamstrings stretch, flat back. **Alternative:** since you have 2lb practice plates + 10lb plates, you could use the empty barbell (35lb) as a light RDL instead and add small increments over coming weeks — this lets you progress in much smaller jumps than jumping between kettlebell weights, which is genuinely useful given the hypermobility (smaller, more controllable load increases)', '{"targetText":"3 x 10"}', 10);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-glute-bridge', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Glute bridge', 'If you don''t feel this in your glutes (common), try: feet closer to your hips, a resistance band looped just above your knees (push knees out against the band), and pause 2 sec at the top squeezing hard. If it''s still not landing, this exercise can be dropped for now — feeling it matters more than doing it', '{"targetText":"3 x 12"}', 11);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-split-squat-rear-foot-elevated-optional', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Split squat (rear foot elevated optional)', 'Bodyweight or light dumbbells (5-8 lb each hand) — this covers the unilateral leg work walking lunges would, without needing lunge-length floor space', '{"targetText":"2 x 10/side"}', 12);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-2-wednesday-lower-body-technique-day-standing-calf-raise', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Standing calf raise', 'Bodyweight', '{"targetText":"3 x 15"}', 13);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-powerblock-incline-press-feet-up-on-benc', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Powerblock incline press (feet up on bench or use floor angle)', '15-20 lb each hand', '{"targetText":"3 x 10"}', 14);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-pulley-seated-row', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Pulley seated row', 'Moderate tension — squeeze at the back, controlled return', '{"targetText":"3 x 12"}', 15);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-powerblock-lateral-raise', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Powerblock lateral raise', '5-8 lb — light, controlled, no swinging', '{"targetText":"3 x 12"}', 16);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-negative-pull-ups-jump-to-top-lower-slow', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Negative pull-ups (jump to top, lower slow 3-5 sec)', 'Bodyweight — builds toward real pull-ups', '{"targetText":"3 x 3-5"}', 17);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-push-up-progression', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Push-up progression', 'Same incline push-up as Monday — lower the incline (e.g., a lower surface) once 8+ reps feel easy at current height', '{"targetText":"3 x max effort"}', 18);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-kettlebell-suitcase-carry', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Kettlebell suitcase carry', '20-25 lb — given the tight space, do this as a slow walk on the treadmill instead (very low speed, ~1 mph), holding the kettlebell at your side, core braced', '{"targetText":"3 x 20 steps/side"}', 19);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-4-friday-upper-body-volume-day-dumbbell-hammer-curl', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Dumbbell hammer curl', '8-12 lb', '{"targetText":"2 x 12"}', 20);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-kettlebell-goblet-squat', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Kettlebell goblet squat', '15-20 lb — same cues as Tuesday', '{"targetText":"3 x 10"}', 21);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-kettlebell-deadlift-standing-over-kb-or-', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Kettlebell deadlift (standing over KB, or sumo stance)', '25-30 lb — hinge, flat back, drive through heels. **Stand on the plywood platform if it fits your stance**, otherwise plain carpet is fine here since it''s a lighter, more controlled lift than the squat', '{"targetText":"3 x 8"}', 22);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-walking-lunge', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Walking lunge', 'Given tight space, do **reverse lunges in place** instead (step back, not forward — needs less room, and is generally easier to balance for hypermobile knees since there''s less forward knee travel)', '{"targetText":"3 x 10/side"}', 23);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-hip-thrust-feet-on-floor-shoulders-on-be', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Hip thrust (feet on floor, shoulders on bench)', 'If you don''t feel this either (also common), try: band above the knees pushing out, feet a bit closer to your hips, chin tucked (not thrown back), and pause hard at the top. Same rule as the glute bridge — if it''s still not landing after trying these tweaks, it''s fine to drop for now', '{"targetText":"3 x 12"}', 24);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-side-lying-leg-raise-or-band-walk', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Side-lying leg raise or band walk', 'Hip stability — helpful for knee tracking in squat', '{"targetText":"2 x 15/side"}', 25);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-propulsion-day-5-saturday-lower-body-volume-day-plank', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Plank', 'Bodyweight', '{"targetText":"3 x 20-30 sec"}', 26);
INSERT OR REPLACE INTO categories (id, program_id, name, label, kind, sort_order) VALUES ('week1-fuel-cells', 'week1', 'fuel-cells', 'FUEL CELLS', 'checkbox', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-daily-early-morning-coffee-light-protein', 'week1-fuel-cells', NULL, 'Early Morning — Coffee + Light Protein', '100-120 kcal · 8-10g protein', '{"mealType":null,"recipe":{"title":"Early Morning — Coffee + Light Protein","prepTime":null,"metaFields":[],"nutrition":{"Calories":"100-120","Protein":"8-10g","Fat":"1-2g","Carbs":"1-2g"},"ingredientSets":[{"label":"Option A: Hard-boiled egg","items":["1 large pre-made hard-boiled egg","200mL coffee","30mL oat milk (lactose-free)"]},{"label":"Option B: Protein shake","items":["200mL lactose-free milk","15g pea or soy protein powder","200mL water"]}],"instructionSets":[{"label":"Instructions (Option A)","steps":["Brew coffee.","Warm oat milk slightly or add cold, as desired.","Peel egg and eat alongside."]},{"label":"Instructions (Option B)","steps":["Brew coffee.","In a separate cup, shake protein powder with milk and water until smooth.","Drink the shake separately or stir into coffee if desired."]}],"note":null}}', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-daily-mid-morning-protein-snack-10-30-11am', 'week1-fuel-cells', NULL, 'Mid-Morning — Protein Snack (~10:30-11am)', '280-320 kcal · 24-26g protein', '{"mealType":null,"recipe":{"title":"Mid-Morning — Protein Snack (~10:30-11am)","prepTime":null,"metaFields":[],"nutrition":{"Calories":"280-320","Protein":"24-26g","Fat":"3-5g","Carbs":"35-40g","Fiber":"2-3g"},"ingredientSets":[{"label":null,"items":["180mL lactose-free plain Greek-style yogurt","60mL granola (Bear Naked Protein recommended)","75g mixed berries (fresh or thawed frozen)","1 large pre-made hard-boiled egg, peeled"]}],"instructionSets":[{"label":null,"steps":["Pour yogurt into a bowl.","Top with granola and berries.","Place the peeled egg on the side or chopped into the yogurt.","Eat immediately."]}],"note":null}}', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-daily-afternoon-snack-protein-shake', 'week1-fuel-cells', NULL, 'Afternoon Snack — Protein Shake', '160 kcal · 30g protein', '{"mealType":null,"recipe":{"title":"Afternoon Snack — Protein Shake","prepTime":null,"metaFields":[],"nutrition":{"Calories":"160","Protein":"30g","Fat":"2-3g","Carbs":"4-5g"},"ingredientSets":[{"label":null,"items":["1 can (330mL) Slate Ultra Protein shake"]}],"instructionSets":[{"label":null,"steps":["Open can, pour into a glass or drink directly from can."]}],"note":null}}', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-mon-tofu-chickpea-bowl-lunch', 'week1-fuel-cells', 'Mon', 'Tofu & Chickpea Bowl (Lunch)', '540 kcal · 32g protein', '{"mealType":"lunch","recipe":{"title":"Tofu & Chickpea Bowl","prepTime":"25 min","metaFields":[{"label":"Prep time","value":"25 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"540","Protein":"32g","Fat":"14g","Carbs":"70g","Fiber":"14g"},"ingredientSets":[{"label":null,"items":["200g extra-firm tofu, pressed","15mL soy sauce","15mL cornstarch","1 can (425g) chickpeas, drained and rinsed","5mL olive oil","Pinch salt, paprika","200g roasted sweet potato (pre-batch cooked)","250mL roasted veggies (broccoli/peppers)","15-22mL tahini","Juice of 1/2 lemon (15mL)","15-30mL water","Pinch salt (for dressing)"]}],"instructionSets":[{"label":null,"steps":["Pat tofu dry with paper towels. Press between two plates for 5-10 min to remove moisture.","Cube the pressed tofu into 2.5cm pieces.","Toss tofu cubes in soy sauce, then coat evenly with cornstarch.","Pat chickpeas dry with paper towels. Toss with 5mL olive oil, salt, and paprika.","Air fry tofu at 200°C for 12 min, shaking the basket halfway through.","Air fry chickpeas at 200°C for 10-12 min, shaking halfway through (use a separate batch if space is limited).","While cooking, whisk tahini, lemon juice, 15-30mL water, and a pinch of salt until smooth. Add more water if the dressing is too thick.","Warm sweet potato and roasted veggies (microwave 1-2 min, or air fry 3-4 min at 200°C).","Assemble: sweet potato and roasted veggies as the base, top with tofu and chickpeas, drizzle with tahini sauce."]}],"note":null}}', 3);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-mon-tofu-steaks-dinner', 'week1-fuel-cells', 'Mon', 'Tofu Steaks (Dinner)', '480 kcal · 30g protein', '{"mealType":"dinner","recipe":{"title":"Tofu Steaks","prepTime":"20 min","metaFields":[{"label":"Prep time","value":"20 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"480","Protein":"30g","Fat":"12g","Carbs":"58g","Fiber":"9g"},"ingredientSets":[{"label":null,"items":["200g extra-firm tofu, pressed","15mL soy sauce","5mL ginger-garlic paste","500mL broccoli and carrots, chopped (approx 300g)","5mL olive oil","Salt, pepper to taste","160mL cooked farro (dry weight ~55g)"]}],"instructionSets":[{"label":null,"steps":["Press tofu for 5-10 min as above.","Slice pressed tofu into 3-4 slabs (approximately 1.3cm thick each).","Combine soy sauce and ginger-garlic paste in a shallow bowl. Marinate tofu slices for at least 10 min.","Air fry tofu at 200°C for 15 min, flipping halfway through.","Toss broccoli and carrots with 5mL olive oil, salt, and pepper.","Air fry veggies at 200°C for 12-15 min (can run before or after tofu, or simultaneously in a second basket).","Cook farro ahead: per package directions, or pressure cooker method: 85mL farro + 170mL water, high pressure 10 min, quick release.","Plate tofu steaks and roasted veggies over farro."]}],"note":null}}', 4);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-tue-ground-turkey-taco-bowl-lunch', 'week1-fuel-cells', 'Tue', 'Ground Turkey Taco Bowl (Lunch)', '550 kcal · 34g protein', '{"mealType":"lunch","recipe":{"title":"Ground Turkey Taco Bowl","prepTime":"15 min","metaFields":[{"label":"Prep time","value":"15 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"550","Protein":"34g","Fat":"16g","Carbs":"60g","Fiber":"8g"},"ingredientSets":[{"label":null,"items":["150g ground turkey","2.5mL chili powder","2.5mL paprika","2.5mL dried oregano","Pinch salt","160mL cooked rice (dry weight ~55g)","125mL black beans, canned and drained","1 small handful shredded lettuce (approx 30g)","30mL salsa","1/4 medium avocado, sliced (approx 50g)"]}],"instructionSets":[{"label":null,"steps":["Heat a nonstick skillet over medium-high heat (no oil needed).","Add ground turkey, breaking it up with a spatula as it cooks.","Season with chili powder, paprika, oregano, and salt. Cook for 8-10 min until browned through (internal temp 74°C).","Warm black beans separately in microwave (2-3 min) or small pot.","Build the bowl: rice on the bottom, then turkey and beans on top, then lettuce, salsa, and avocado slices."]}],"note":null}}', 5);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-tue-ground-beef-veggie-stir-fry-dinner', 'week1-fuel-cells', 'Tue', 'Ground Beef & Veggie Stir-Fry (Dinner)', '560 kcal · 26g protein', '{"mealType":"dinner","recipe":{"title":"Ground Beef & Veggie Stir-Fry","prepTime":"15 min","metaFields":[{"label":"Prep time","value":"15 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"560","Protein":"26g","Fat":"28g","Carbs":"50g","Fiber":"4g"},"ingredientSets":[{"label":null,"items":["150g Walden Local 80/20 ground beef","500mL mixed stir-fry veggies (fresh or frozen, approx 300g)","15mL soy sauce","5mL ginger-garlic paste","2.5mL sesame oil (optional)","160mL cooked rice (dry weight ~55g)"]}],"instructionSets":[{"label":null,"steps":["Heat a nonstick skillet over medium-high heat.","Add ground beef, breaking it apart with a spatula as it cooks, about 6-8 min.","Tilt the pan and spoon off rendered fat (drain into a small bowl or directly into trash). Alternatively, transfer cooked beef to a strainer and rinse briefly with hot water for a leaner result.","Return beef to the pan. Add ginger-garlic paste, cook 30 seconds until fragrant.","Add stir-fry veggies and soy sauce. Stir-fry for 4-5 min until crisp-tender.","Drizzle with sesame oil if using.","Serve over rice."]}],"note":null}}', 6);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-wed-chickpea-salad-lunch', 'week1-fuel-cells', 'Wed', 'Chickpea Salad (Lunch)', '480 kcal · 22g protein', '{"mealType":"lunch","recipe":{"title":"Chickpea Salad","prepTime":"10 min","metaFields":[{"label":"Prep time","value":"10 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"480","Protein":"22g","Fat":"16g","Carbs":"60g","Fiber":"14g"},"ingredientSets":[{"label":null,"items":["500mL mixed greens (approx 120g)","1 can (425g) chickpeas, drained and rinsed, or 375mL cooked chickpeas (approx 420g)","1/2 medium cucumber, sliced (approx 120g)","30mL lactose-free feta (approx 30g) OR handful of olives (approx 25g)","15mL olive oil","15mL vinegar (red wine or apple cider)","Salt, pepper to taste"]}],"instructionSets":[{"label":null,"steps":["Place mixed greens in a bowl.","Add chickpeas, cucumber slices, and feta or olives.","In a small bowl or jar, whisk together olive oil, vinegar, salt, and pepper.","Drizzle dressing over the salad and toss well to combine."]}],"note":null}}', 7);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-wed-chana-masala-dinner', 'week1-fuel-cells', 'Wed', 'Chana Masala (Dinner)', '500 kcal · 25g protein', '{"mealType":"dinner","recipe":{"title":"Chana Masala","prepTime":"20 min","metaFields":[{"label":"Prep time","value":"20 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"500","Protein":"25g","Fat":"16g","Carbs":"65g","Fiber":"12g"},"ingredientSets":[{"label":null,"items":["1 can (425g) chickpeas, drained (or 350mL cooked chickpeas)","1/2 medium onion, diced (approx 60g)","5-10mL ginger-garlic paste","1 can (400mL) diced tomatoes","5mL turmeric","5mL garam masala","2.5mL ground coriander","15mL oil","Salt to taste","60mL water","160mL cooked rice (dry weight ~55g)"]}],"instructionSets":[{"label":"Pressure Cooker Instructions","steps":["Set pressure cooker to sauté mode. Heat 15mL oil.","Add diced onion, cook 3-4 min until softened.","Add ginger-garlic paste, cook 30 seconds until fragrant.","Add canned tomatoes (with juice), turmeric, garam masala, coriander, and salt. Stir.","Add drained chickpeas and 60mL water. Stir.","Seal cooker, cook on high pressure for 5 min.","Allow natural release for 5 min, then quick release remaining pressure.","Stir and adjust seasoning. Serve over rice."]},{"label":"Stovetop Instructions","steps":["Heat 15mL oil in a pot over medium heat.","Add diced onion, cook 3-4 min until softened.","Add ginger-garlic paste, cook 30 seconds.","Add canned tomatoes (with juice), turmeric, garam masala, coriander, and salt. Stir.","Add drained chickpeas and 60mL water.","Bring to a simmer, then reduce heat to low.","Simmer uncovered for 15-20 min until thickened, stirring occasionally.","Adjust seasoning and serve over rice."]}],"note":null}}', 8);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-thu-red-lentil-dal-lunch', 'week1-fuel-cells', 'Thu', 'Red Lentil Dal (Lunch)', '480 kcal · 24g protein', '{"mealType":"lunch","recipe":{"title":"Red Lentil Dal","prepTime":"20 min","metaFields":[{"label":"Prep time","value":"20 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"480","Protein":"24g","Fat":"10g","Carbs":"70g","Fiber":"10g"},"ingredientSets":[{"label":null,"items":["175mL dry red lentils, rinsed","355mL water or broth","1/2 medium onion, diced (approx 60g)","5mL ginger-garlic paste","2.5mL turmeric","2.5mL garam masala","1.25mL ground coriander","15mL oil","Salt to taste","160mL cooked rice (dry weight ~55g)"]}],"instructionSets":[{"label":"Pressure Cooker Instructions","steps":["Set pressure cooker to sauté mode. Heat 15mL oil.","Add diced onion, cook 3-4 min until softened.","Add ginger-garlic paste, turmeric, garam masala, and coriander. Cook 30 seconds until fragrant.","Add rinsed lentils and 355mL water or broth. Stir.","Seal cooker, cook on high pressure for 5 min.","Allow natural release for 10 min, then quick release any remaining pressure.","Stir, season with salt to taste, and serve over rice."]},{"label":"Stovetop Instructions","steps":["Heat 15mL oil in a pot over medium heat.","Add diced onion, cook 3-4 min until softened.","Add ginger-garlic paste, turmeric, garam masala, and coriander. Cook 30 seconds.","Add rinsed lentils and 355mL water or broth.","Bring to a boil, then reduce heat to low and simmer for 15-20 min until lentils are soft and soup thickens, stirring occasionally.","Season with salt to taste and serve over rice."]}],"note":null}}', 9);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-thu-turkey-meatballs-marinara-dinner', 'week1-fuel-cells', 'Thu', 'Turkey Meatballs + Marinara (Dinner)', '500 kcal · 40g protein', '{"mealType":"dinner","recipe":{"title":"Turkey Meatballs + Marinara","prepTime":"15 min","metaFields":[{"label":"Prep time","value":"15 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"500","Protein":"40g","Fat":"8g","Carbs":"55g","Fiber":"4g"},"ingredientSets":[{"label":null,"items":["150g ground turkey","Salt, pepper to taste","2.5mL dried oregano","240mL marinara sauce","56g Barilla Protein+ pasta (dry weight) OR 200g spiralized zucchini"]}],"instructionSets":[{"label":null,"steps":["Mix ground turkey with salt, pepper, and dried oregano in a bowl.","Form mixture into 4-5 meatballs (approximately 30-35g each).","Air fry meatballs at 193°C for 10-12 min, turning halfway through, until internal temp reaches 74°C.","While meatballs cook, warm marinara sauce in a small pot over medium heat (about 5 min).","If using pasta: cook per package directions (typically 8-10 min), drain. If using zucchini noodles: sauté in a nonstick pan for 2-3 min.","Combine cooked meatballs with marinara sauce.","Serve over cooked pasta or zucchini noodles."]}],"note":null}}', 10);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-fri-meatball-bowl-lunch', 'week1-fuel-cells', 'Fri', 'Meatball Bowl (Lunch)', '520 kcal · 33g protein', '{"mealType":"lunch","recipe":{"title":"Meatball Bowl","prepTime":"15 min","metaFields":[{"label":"Prep time","value":"15 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"520","Protein":"33g","Fat":"10g","Carbs":"62g","Fiber":"8g"},"ingredientSets":[{"label":null,"items":["150g ground turkey (same meatball preparation as Thursday)","Salt, pepper, 2.5mL dried oregano","250mL roasted veggies (broccoli/carrots/peppers, pre-roasted)","160mL cooked farro (dry weight ~55g)"]}],"instructionSets":[{"label":null,"steps":["Prepare meatballs as per Thursday recipe.","Air fry at 193°C for 10-12 min as above.","Warm pre-roasted veggies (microwave 1-2 min or air fry 3-4 min).","Cook farro ahead per package directions or pressure cooker (85mL farro + 170mL water, high pressure 10 min).","Assemble bowl: farro on the bottom, top with meatballs and roasted veggies."]}],"note":"Make a double batch of meatballs on Thursday to cover both Thursday dinner and Friday lunch if preferred."}}', 11);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-fri-black-bean-tacos-dinner', 'week1-fuel-cells', 'Fri', 'Black Bean Tacos (Dinner)', '480 kcal · 20g protein', '{"mealType":"dinner","recipe":{"title":"Black Bean Tacos","prepTime":"10 min","metaFields":[{"label":"Prep time","value":"10 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"480","Protein":"20g","Fat":"14g","Carbs":"65g","Fiber":"12g"},"ingredientSets":[{"label":null,"items":["1 can (425g) black beans, drained and rinsed (or 310mL cooked beans)","2.5mL chili powder","2.5mL paprika","Pinch salt","3 corn tortillas","1/4 medium avocado, sliced (approx 50g)","30mL salsa","30mL lactose-free sour cream"]}],"instructionSets":[{"label":null,"steps":["Add drained black beans to a small pot with chili powder, paprika, and salt.","Warm over medium heat for about 5 min, mashing lightly with a fork if you prefer a thicker texture (optional).","Warm tortillas in a dry nonstick pan (30 sec per side) or wrap in a damp paper towel and microwave (30 sec).","Fill each tortilla with beans, then top with avocado slices, salsa, and sour cream.","Serve immediately."]}],"note":null}}', 12);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-sun-white-bean-veggie-soup-dinner', 'week1-fuel-cells', 'Sun', 'White Bean & Veggie Soup (Dinner)', '460 kcal · 23g protein', '{"mealType":"dinner","recipe":{"title":"White Bean & Veggie Soup","prepTime":"20 min","metaFields":[{"label":"Prep time","value":"20 min"},{"label":"Serves","value":"1"}],"nutrition":{"Calories":"460","Protein":"23g","Fat":"12g","Carbs":"60g","Fiber":"14g"},"ingredientSets":[{"label":null,"items":["1 can (425g) white beans, drained and rinsed (or 350mL cooked beans)","500mL chopped kale (approx 140g)","1 can (400mL) diced tomatoes","1/2 medium onion, diced (approx 60g)","5mL minced garlic (or 2.5mL garlic paste)","480mL broth or water","15mL olive oil","Salt, pepper, dried oregano to taste","1 slice (35g) whole grain bread"]}],"instructionSets":[{"label":"Pressure Cooker Instructions","steps":["Set pressure cooker to sauté mode. Heat 15mL oil.","Add diced onion and garlic, cook 3 min until softened.","Add canned tomatoes (with juice), white beans, chopped kale, 480mL broth, salt, pepper, and dried oregano. Stir.","Seal cooker, cook on high pressure for 8-10 min.","Quick release pressure.","Stir and adjust seasoning if needed.","Serve with whole grain bread on the side."]},{"label":"Stovetop Instructions","steps":["Heat 15mL oil in a pot over medium heat.","Add diced onion and garlic, cook 3 min until softened.","Add canned tomatoes (with juice), white beans, chopped kale, 480mL broth, salt, pepper, and dried oregano. Stir.","Bring to a simmer, reduce heat to low, and simmer for 15-20 min, stirring occasionally.","Adjust seasoning and serve with whole grain bread."]}],"note":null}}', 13);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-fuel-cells-daily-morning-wellness-shot-weekly-prep', 'week1-fuel-cells', NULL, 'Morning Wellness Shot (weekly prep)', '10-15 kcal · 0g protein', '{"mealType":null,"recipe":{"title":"Morning Wellness Shot","prepTime":"5 min","metaFields":[{"label":"Prep time","value":"5 min"},{"label":"Makes","value":"5-6 one-ounce (30mL) shots"},{"label":"Keeps","value":"4-5 days refrigerated"}],"nutrition":{"Calories":"10-15","Protein":"0g","Fat":"0g","Carbs":"2-3g","Fiber":"0g"},"ingredientSets":[{"label":null,"items":["5cm piece fresh ginger, peeled (approx 15g) OR 30mL ginger paste","5mL ground turmeric (or 5cm piece fresh turmeric root)","30mL fresh lemon juice (from 2 lemons)","1.25mL black pepper","45mL raw, unfiltered apple cider vinegar with \"the mother\"","80mL water","Optional: 5mL honey"]}],"instructionSets":[{"label":null,"steps":["If using fresh ginger or turmeric root: peel and roughly chop.","Add ginger, turmeric, lemon juice, black pepper, apple cider vinegar, water, and honey (if using) to a blender.","Blend on high speed until completely smooth (30-60 seconds).","If using fresh ginger/turmeric, strain through a fine mesh strainer or cheesecloth to remove fiber.","Pour into small glass jars or shot glasses.","Refrigerate immediately.","Take one 1oz (30mL) shot each morning. Shake before pouring if separation occurs."]}],"note":"The live cultures in ACV with the mother provide mild probiotic benefits, but this is not a replacement for your regular probiotic gummy supplement."}}', 14);
