INSERT OR REPLACE INTO categories (id, program_id, name, label, kind, sort_order) VALUES ('week1-life-support', 'week1', 'life-support', 'LIFE SUPPORT', 'checkbox', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-sleep', 'week1-life-support', NULL, 'Sleep', 'Given your work hours swing (7am-10pm on intense days), a fixed bedtime isn''t realistic — so anchor on wake time instead, which matters more for your body''s rhythm anyway. · Wake time: 6:30am, every day, including weekends. This is the one non-negotiable. A consistent wake time regulates hunger hormones, energy, and workout performance far more than a consistent bedtime does. · Target 7-8 hours of sleep, meaning bedtime by 10:30-11:30pm depending on when you woke up feeling rested. · Wind-down routine (last 30 min before bed): no food, dim lights, phone away from bed (or on do-not-disturb). If you train in the evening, leave at least 1-2 hours between finishing your workout and getting in bed — training too close to sleep can delay falling asleep. · On late work nights (until 10pm): still hold the 6:30am wake time if possible. One short night is fine; the consistency matters more long-term than any single night''s total hours. · Use your Fitbit Inspire 3''s sleep tracking to see actual sleep duration and quality, not just time in bed — it''ll tell you if you''re getting real 7-8 hours or just lying there.', NULL, 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-hydration', 'week1-life-support', NULL, 'Hydration', 'Target: half your bodyweight in ounces, minimum — at ~150 lb, that''s ~75 oz (about 9 cups) per day, more on training days or hot days. · Simplest approach: keep a marked water bottle at your desk (WFH makes this easy) and refill it 2-3x through the day rather than tracking ounces manually. · Drink a glass of water first thing when you wake up and one with each meal — removes most of the "remembering to drink water" problem on its own.', NULL, 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-with-breakfast-or-mid-morning-snack', 'week1-life-support', NULL, 'With breakfast (or mid-morning snack)', 'Multi + Omega-3 (Women''s), B-12 — Take with food for better absorption', NULL, 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-with-lunch', 'week1-life-support', NULL, 'With lunch', 'Calcium + D3 gummies — Separate from iron by a few hours (calcium blocks iron absorption)', NULL, 3);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-with-dinner-or-evening', 'week1-life-support', NULL, 'With dinner or evening', 'Probiotic — Consistency matters more than exact timing — same time daily is the main thing', NULL, 4);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, meta, sort_order) VALUES ('week1-life-support-daily-only-on-days-you-haven-t-had-much-red-me', 'week1-life-support', NULL, 'Only on days you haven''t had much red meat', 'Iron — Take with a vitaminC-containing food (citrus, berries) for better absorption, and **away from the calcium gummies and any Metamucil** by a few hours', NULL, 5);
